import { useFinanceStore } from '../store'
import { accountAvailableBalance, accountBalance, formatCurrency, localDate } from '../lib/finance'

/** Displays only explicitly source-linked savings and active reservations, not a new computed balance. */
export function AccountAllocation({ accountId }: { accountId: string }) {
  const transactions = useFinanceStore((state) => state.transactions)
  const plans = useFinanceStore((state) => state.plannedSpending)
  const account = useFinanceStore((state) => state.accounts.find((item) => item.id === accountId))
  const transfers = useFinanceStore((state) => state.transfers)
  const contributions = useFinanceStore((state) => state.contributions)
  const adjustments = useFinanceStore((state) => state.balanceAdjustments)
  const goalContributions = useFinanceStore((state) => state.goalContributions)
  const budgetSchedules = useFinanceStore((state) => state.budgetSchedules)
  const budgetOccurrences = useFinanceStore((state) => state.budgetOccurrences)
  const savings = transactions.filter((entry) => entry.type === 'saving' && entry.mode !== 'opening' && entry.accountId === accountId).reduce((sum, entry) => sum + entry.amount, 0)
  const goalReserved = goalContributions.filter((entry) => entry.accountId === accountId && entry.type === 'reserve').reduce((sum, entry) => sum + entry.amount, 0)
  const budgetReserved = plans.filter((plan) => plan.accountId === accountId && plan.reserveMoney && plan.date >= localDate() && ['Upcoming', 'Active'].includes(plan.status)).reduce((sum, plan) => sum + plan.maximumAmount, 0)
  const physical = account ? accountBalance(account, transactions, transfers, contributions, adjustments) : 0
  const available = account ? accountAvailableBalance(account, transactions, transfers, contributions, adjustments, plans, goalContributions, budgetSchedules, budgetOccurrences) : 0
  const scheduledBudgetReserved = budgetOccurrences.filter((occurrence) => occurrence.status === 'scheduled' || occurrence.status === 'due').filter((occurrence) => budgetSchedules.some((schedule) => schedule.id === occurrence.budgetScheduleId && schedule.status === 'active' && schedule.reservationMode === 'reserve' && schedule.sourceAccountId === accountId)).reduce((sum, occurrence) => sum + occurrence.plannedAmount, 0)
  return <div className="account-allocation"><span>Physical balance <strong>{formatCurrency(physical)}</strong></span><span>Savings allocation <strong>{formatCurrency(savings)}</strong></span><span>Goal reservation <strong>{formatCurrency(goalReserved)}</strong></span><span>Budget reservation <strong>{formatCurrency(budgetReserved + scheduledBudgetReserved)}</strong></span><span>Available balance <strong>{formatCurrency(available)}</strong></span></div>
}